const section = (id, ru, en, bodyRu, bodyEn) => ({ id, ru, en, bodyRu, bodyEn });
export const OBJECT_HELP_PAGES = [
  { id: "commands", ru: "Поручить действия спутнику", en: "Give a companion commands", sections: [
    section("prepare", "Разрешить нужные команды", "Allow the intended commands", "Откройте «Поведение объекта → Команды». Все команды сначала выключены. Отметьте нужные и нажмите «Настроить»: задайте теги командующего персонажа, расстояние и допустимые группы со состояниями. Сохраните. Пустой список групп разрешает любые состояния; пустой список состояний выбранной группы разрешает все её состояния. Запрещающий тег отменяет разрешающий.", "Open Object behavior → Commands. All commands start disabled. Enable the ones you need and choose Configure: set the commanding character's tags, range, and allowed groups and states. Save. An empty group list allows any state; an empty state list within a selected group allows all its states. A denied tag overrides an allowed one."),
    section("give", "Выдать команду от персонажа", "Issue a command as a character", "Выберите своего персонажа и откройте меню объекта. Доступны только разрешённые команды. Для «Встань там» укажите видимую персонажу точку, для «Патрулируй» — две точки, для двери — нужную дверь. Выбор двери не открывает её сам. Плашка под исполнителем показывает имя командующего и текущую команду. Если условия не выполнены, игрок и мастер получают понятное предупреждение.", "Choose your character and open the object's menu. Only enabled commands are available. Stand there asks for a point visible to your character, Patrol for two points, and door commands for a door. Picking the door does not itself open it. A badge below the performer shows the commanding character and current command. Failed conditions give both the player and GM a readable warning."),
    section("replacement", "Заменить команду после текущего скрипта", "Replace a command after its current script", "Если выполняется скрипт до или после команды и в нём выбрано «Командой → Игнорировать», принятые «Жди» или «Отмена» сначала дождутся конца этого блока. Плашка покажет «Затем:» и следующую команду. Оставшиеся части прежней команды не выполняются. В ожидании допускается одна замена; остальные заявки отклоняются. «Стой» срабатывает немедленно, даже при «Игнорировать».", "If a preceding or following script is running with Command → Ignore, an accepted Wait or Cancel first waits for that block to finish. The badge shows Next and the waiting command. The old command's remaining parts do not run. Only one replacement can wait; other requests are rejected. Stop takes effect immediately, even when Ignore is selected."),
    section("admission", "Сохранить выполнение после начала движения", "Keep a moving command running", "Теги, дальность и разрешённые состояния проверяются при приёме команды. Если затем персонаж отходит дальше, уже принятую команду это не отменяет: спутник может продолжить следование. Смена состояния группы исполнителя, удаление объекта или ручная остановка по-прежнему влияют на выполнение. Ожидание предыдущего скрипта не считается началом самой команды; она начинается со своего предваряющего скрипта.", "Tags, range and allowed states are checked when accepting a command. If the character later moves farther away, that does not cancel an accepted command: a companion can keep following. A state change in the performer's group, removal of the object or a manual stop still affects execution. Waiting for a previous script does not count as starting the command itself; it starts with its own preceding script."),
    section("movement", "Попросить подойти, отойти или следовать", "Ask a companion to approach, move away or follow", "«Подойди» и «Отойди» идут по прямой со скоростью и ограничением длительности; препятствие останавливает движение. «Встань там» после движения ждёт указанное время. «Следуй за мной» использует минимальную и максимальную дистанции и выбранный способ следования. «Патрулируй» ходит между двумя точками. «Жди» заменяет текущую команду движения и удерживает объект на месте. Время ожидания и длительность должны быть больше нуля.", "Come here and Move away travel in a straight line at the configured speed until their time limit; an obstacle stops movement. Stand there waits for the configured time after moving. Follow me uses minimum and maximum gaps and the selected following mode. Patrol moves between two points. Wait replaces an active movement command and holds the object in place. Wait times and durations must be greater than zero."),
    section("interaction", "Открыть путь и включить свет", "Open a route and turn on a light", "«Открой дверь» и «Закрой дверь» подводят исполнителя к указанной двери. «Зажги свет» включает сопровождающий его источник с ярким и тусклым радиусами; «Потуши свет» убирает этот источник. Обычная новая команда занятому исполнителю отклоняется. «Стой» останавливает всю его автоматизацию, «Отмена» завершает команду и задаёт ожидание; настройте, кто вправе их выдавать.", "Open the door and Close the door move the performer to the selected door. Light on enables a source that follows it, using the configured bright and dim radii; Light off removes that source. A busy performer rejects a new ordinary command. Stop halts all of its automation; Cancel ends the command and waits. Configure who may issue these controls."),
    section("interruptions", "Продолжить команду после помехи", "Continue a command after an interruption", "В «При прерывании команды» настройте бой, взаимодействие, ручную остановку и ошибку. По умолчанию команда прерывается. «Начать текущую фазу заново» повторяет скрипт до команды, встроенное действие или скрипт после — смотря где произошла остановка. «Перейти к следующей фазе» пропускает остаток текущей; после последней завершает команду. «Начать команду заново» возвращает к предваряющему скрипту. Продолжение ждёт окончания помехи; после ручной остановки нужен явный запуск. Совершённые действия не откатываются.", "Under When the command is interrupted, configure combat, interaction, manual stop and error behavior. By default the command stops. Restart the current phase repeats the preceding script, built-in action or following script, depending on where it stopped. Go to the next phase skips the current remainder and completes after the last phase. Restart the command returns to the preceding script. Continuation waits for the interruption to end; a manual stop requires an explicit start. Completed actions are not rolled back."),
    section("scripts", "Добавить подготовку и завершение", "Add preparation and completion", "Под настройками команды создайте скрипт «До команды» или «После команды». Пользуйтесь общим редактором, импортом и экспортом JSON. Команда занимает объект от начала первого скрипта до конца последнего. При прерывании командой вложенный скрипт по умолчанию выбирает «Игнорировать». Если уже выполняющийся скрипт игнорирует команду, принятая команда ждёт его завершения, а новая рутина не начинается. Бесконечный повтор может удерживать это ожидание: вмешайтесь через «Стой», «Отмена» или остановку мастером.", "Below the command settings, create a Before command or After command script. Use the shared editor and JSON import/export. The command occupies the object from the first script's start to the last script's completion. Nested scripts default to Ignore for command interruption. If an already active script ignores commands, an accepted command waits for it to finish and no new routine starts. An endless loop can hold that wait: intervene with Stop, Cancel, or a GM stop.")
  ] },
  { id: "objects", ru: "Подготовить объекты сцены", en: "Prepare scene objects", sections: [
    section("refresh", "Продолжить работу после изменения связанных данных", "Continue after related data changes", "Открытые окна обновляют названия и списки связанных объектов. Несохранённый ввод остаётся в форме. Если выбранная запись удалена, выберите доступную заново. Если те же настройки уже изменили в другом окне, сохранение предложит обновить данные: сохраните нужный текст отдельно перед повторным открытием формы.", "Open windows refresh the names and lists of related objects. Unsaved input stays in the form. If the selected entry was deleted, choose an available one again. If the same settings were changed in another window, saving asks you to reload the data: copy any text you need before reopening the form."),
    section("menu", "Найти и проверить объект", "Find and inspect an object", "В Конструкторе выберите слой Foundry и кликните токен, тайл, рисунок, стену, свет, звук, заметку, шаблон или область. Меню открывает «Информацию» и «Поведение». Другой инструмент слева не закрывает Ширму. Выбор объекта в «Автоматизации» центрирует карту, включает его слой и выделяет объект рамкой.", "In Constructor, select a Foundry layer and click a token, tile, drawing, wall, light, sound, note, template or region. The menu opens Information and Behavior. Changing the scene tool keeps Master screen open. Selecting an object in Automation centers the map, activates its layer and outlines it."),
    section("owner", "Назначить группу и заметки", "Assign a group and notes", "В «Информации» выберите группу, теги и заметки. У каждого выведенного значения есть кнопка копирования; «Настройки» открывает штатное окно объекта. Enter сохраняет и закрывает, Shift+Enter добавляет строку заметки. Один объект принадлежит одной группе. Привязку удалённого объекта можно убрать из таблицы группы.", "In Information, choose the group, tags and notes. Each displayed value has a copy button; Settings opens the native object sheet. Enter saves and closes; Shift+Enter inserts a note line. An object belongs to one group. A deleted object's binding can be removed from the group table."),
    section("player", "Подготовить персонажа игрока", "Prepare a player character", "Отметьте «Персонаж игрока»: автоматизация токена отключится, но персонаж сможет обращаться к объектам любых групп без собственной группы. Владение персонажем, дальность, видимость и теги по-прежнему проверяются.", "Enable Player character: the token's automation is disabled, while it may interact across groups without owning a group. Character ownership, range, visibility and tags still apply."),
    section("transitions", "Назначить поведение при смене состояния", "Assign state-entry behavior", "В «Поведение → Переходы» таблица показывает все состояния группы. Нажмите «Создать» или «Править» в нужной строке. Под таблицей откроется скрипт. «Сохранить» оставляет редактор открытым. Подготовка не запускает скрипт; он выполняется при явном переходе в состояние.", "In Behavior → Transitions, the table shows every state in the group. Choose Create or Edit in a row to open its script below. Save leaves the editor open. Preparation does not run the script; an explicit state transition does."),
    section("restore", "Вернуть сцену к началу приключения", "Reset the scene for a new adventure", "Задайте «Исходное состояние» отдельным скриптом: положение, поворот, размеры, видимость и другие необходимые действия. «Восстановить исходное состояние» явно запускает его для этого объекта. Примените подготовленные исходные состояния нужных объектов последовательно. Потраченные предметы и другие факты игры автоматически не восстанавливаются.", "Prepare Initial state as a separate script: position, rotation, size, visibility and other needed actions. Restore initial state explicitly runs it for this object. Apply prepared resets to the required objects in turn. Spent items and other game facts are not automatically restored."),
    section("properties", "Зарегистрировать инструменты объекта", "Register the object's tools", "«Поведение» открывается на вкладке «Свойства». Добавьте магазины и диалоги из каталогов сцены, прикрепите макросы и настройте подписки. Регистрация разрешает использовать инструмент в подготовке объекта, но сама по себе не открывает его игрокам. Один каталог можно зарегистрировать на нескольких объектах.", "Behavior opens on Properties. Add shops and dialogues from the scene catalogs, attach macros and configure subscriptions. Registration makes a tool available when preparing the object, but does not itself grant players access. Several objects can register the same catalog."),
    section("features", "Разрешить действия игроков", "Allow player actions", "В «Действиях игроков» добавьте зарегистрированный магазин или диалог для нужных состояний. Задайте условия запуска, дальность и теги. Эти условия определяют, когда игрок может сам начать взаимодействие. Удаление назначения оставляет инструмент в «Свойствах». Скриптовый вызов диалога мастером обходит эти ограничения.", "In Player actions, add a registered shop or dialogue for the required states. Set activation conditions, range and tags. These conditions determine when a player may initiate interaction. Removing an assignment keeps the tool in Properties. A GM-scripted dialogue bypasses these restrictions."),
    section("automation", "Подключить сигналы и макросы", "Connect signals and macros", "В «Свойствах» объявите сигналы объекта, перетащите или создайте его макросы и настройте подписки. Список показывает, какие скрипты используют макрос. Подписка может слушать собственный объект или другой объект сцены. Перед сохранением подписки Ширма проверит макрос и при необходимости покажет заготовку для редактора Foundry.", "In Properties, declare the object's signals, drop or create its macros and configure subscriptions. The list shows which scripts use a macro. A subscription may listen to this object or another scene object. Before saving, Master screen validates the macro and provides a template for Foundry's editor when needed.")
  ] },
  { id: "scripts", ru: "Собрать скрипт поведения", en: "Build a behavior script", sections: [
    section("interruptions", "Продолжить скрипт после прерывания", "Continue a script after interruption", "В каждом блоке, включая «Исходное состояние», настройте «При прерывании скрипта» отдельно для боя, взаимодействия с игроком, ручной остановки и ошибки. «Прервать» выбрано по умолчанию. Остальные варианты начинают текущий шаг заново, выбирают следующий по его переходам или возвращают к шагу 1. Продолжение ждёт завершения взаимодействия или боя; после ручной остановки нужен явный запуск мастером. Скрипт с «Использовать в бою» не прерывается началом боя или сменой хода. Уже выполненные действия не откатываются, завершённые скрипты после остановки не повторяются.", "In every block, including Initial state, configure When the script is interrupted separately for combat, player interaction, manual stop and errors. Stop is the default. Other modes restart the current step, follow its next graph destination, or return to step 1. Continuation waits until the interaction or combat ends; a manual stop requires an explicit GM start. Use in combat prevents interruption at combat start or turn changes. Completed actions are not rolled back, and completed scripts are not repeated after a stop."),
    section("error-retries", "Ограничить повторение ошибок", "Limit error retries", "Выбрав продолжение при ошибке, задайте «Повторов после ошибки» от 1 до 10 и «Таймаут повторений, с» от 0,1 до 60. По умолчанию — 3 повтора с паузой 1 секунда. Это повторные попытки после первоначальной: максимум 4 попытки при лимите 3. Лимит общий на запуск скрипта; успешные шаги, «Повторять» и ручное продолжение его не пополняют. После исчерпания скрипт останавливается. Новый вход в состояние или новое восстановление исходного состояния дают новый лимит. При «Прервать» поля не действуют, но сохраняют значения.", "When choosing continuation on error, set Retries after an error from 1 to 10 and Retry delay, seconds from 0.1 to 60. Defaults are 3 retries with a 1-second pause. These follow the initial attempt: a limit of 3 allows at most 4 attempts. The budget is shared across one script run; successful steps, Repeat and manual continuation do not replenish it. The script stops once the budget is exhausted. A fresh state entry or initial-state restoration gets a new budget. Stop disables the fields but preserves their values."),
    section("repetition", "Завершить переход и начать рутину", "Finish a transition and start the routine", "Рутина начинается после завершения скрипта перехода. Если переход должен выполниться один раз, снимите в нём «Повторять» и оставьте переход последнего шага пустым. Для повторяющегося поведения с заметным интервалом добавьте «Ожидание». Редактор поведения доступен и во время исполнения скриптов.", "The routine starts after the transition script finishes. For a one-time transition, clear Repeat and leave the last step's Next field empty. Add Wait for repeating behavior with a noticeable interval. The behavior editor remains usable while scripts are running."),
    section("warnings", "Сохранить мгновенный или повторяющийся скрипт", "Save an instant or repeating script", "При сохранении Ширма показывает незаданную длительность и возможные циклы изменённых скриптов. «Цикл без задержек (0 с)» выделен первым: он создаёт наибольший риск перегрузки. Проверьте показанные номера, выходы и «Повторять»; при необходимости добавьте «Ожидание». Эмоция или реплика «Вместе со следующим» не разрывает такой цикл даже с положительной длительностью. Задуманную настройку можно сохранить после подтверждения. Отмена сохраняет ввод и ничего не запускает. Неизменённые блоки повторно не спрашиваются, недостижимые шаги не учитываются.", "When saving, Master screen shows unset durations and possible cycles in edited scripts. Zero-delay cycle (0 sec.) appears first because it poses the highest overload risk. Check the step IDs, exits and Repeat; add Wait if needed. An Emotion or Speech set to Alongside next step does not break such a cycle even with a positive duration. An intentional setup can be saved after confirmation. Cancel keeps your input and starts nothing. Unchanged blocks are not confirmed again; unreachable steps are ignored."),
    section("transfer", "Перенести один блок скрипта", "Transfer one script block", "В раскрытом блоке нажмите «Экспорт JSON», чтобы скачать его актуальные настройки, включая несохранённые значения. «Импорт JSON» предлагает выбрать файл и подтвердить замену только этого блока. Затем нажмите «Сохранить». Привязка к состоянию берётся из текущего блока; диалоги, макросы и сигналы должны быть доступны самому объекту. Отмена сохраняет прежний ввод.", "In an expanded block, press Export JSON to download its current settings, including unsaved values. Import JSON lets you choose a file and confirm replacement of that block only. Then press Save. The destination block determines its state; dialogues, macros and signals must belong to the current object. Cancel preserves the previous input."),
    section("prepare", "Собрать действия для состояния", "Build actions for a state", "Откройте «Поведение → Рутина», выберите строку состояния и создайте скрипт. Задайте понятное название и добавьте шаги. Скрипты исходного состояния и переходов редактируются тем же способом. Без скрипта рутина не выполняется. Сохранение не запускает подготовку.", "Open Behavior → Routine, choose a state row and create a script. Give it a useful name and add steps. Initial-state and transition scripts use the same editor. With no script, no routine runs. Saving does not execute preparation."),
    section("steps", "Управлять порядком действий", "Control action order", "Запуск начинается с шага 1. В «Переходе» один номер задаёт продолжение, несколько номеров через запятую — случайный выбор, пустое поле завершает скрипт. «Повторять» возвращает к шагу 1 после завершения. Чтобы переставить строки для чтения, перетащите ручку слева или нажмите Alt+↑/↓: номера и переходы сохранятся.", "Execution starts at step 1. In Next, one number continues there, several comma-separated numbers choose randomly, and an empty field ends the script. Repeat returns to step 1 after completion. Drag a row's handle or press Alt+Up/Down to arrange rows for reading; IDs and transitions stay unchanged."),
    section("parameters", "Настроить действие без JSON", "Configure an action without JSON", "В столбце параметров меняйте значения рядом с названиями. Строка длительности 0 выделена красным: проверьте, что мгновенное действие задумано намеренно. Это подсказка, а не запрет. Вложенные разделы можно свернуть. Выбранный режим определяет видимые поля; скрытые значения сохраняются. Кнопка JSON у функции открывает все параметры этого шага и синхронизируется с таблицей. Исправьте ошибки JSON перед сохранением.", "Edit values beside their names in the parameters column. A duration of 0 highlights its row in red: check that the instant action is intentional. This is a reminder, not a restriction. Nested sections can be collapsed. The chosen mode determines visible fields while retaining hidden values. JSON beside the function opens all parameters of that step and stays synchronized with the table. Correct JSON errors before saving."),
    section("movement", "Подготовить движение и видимость", "Prepare movement and visibility", "Выберите «Перемещение» и режим «Длительность» или «Скорость». Длительность 0 выполняет действие мгновенно. В «Позиции» заполните координаты из текущего объекта либо кнопкой «Точка с карты»; в «Размере» можно взять текущие размеры. Поворот задаётся в градусах. Размеры и видимость доступны в пределах возможностей объекта; неподдерживаемые измерения не подменяются другими свойствами.", "Choose Move and Duration or Speed mode. Duration 0 acts instantly. Under Position, use the current object coordinates or Map point; under Size, fill the object's current dimensions. Rotation uses degrees. Size and visibility respect the object's native capabilities; unsupported dimensions are not replaced with unrelated properties."),
    section("presentation", "Добавить реплику и звук", "Add speech and sound", "«Реплика» выводит текст в чат, пузырь или оба места. «Режим выполнения → До следующего» по умолчанию ждёт указанную длительность перед следующим шагом; «Вместе со следующим» продолжает скрипт сразу. Длительность 0 не задерживает скрипт и сохраняет реплику до замены. Для чата задайте аудиторию тегами и расстоянием, момент отправки и удаление по завершении. В «Звуке» выбирайте файл штатным менеджером Foundry; множитель громкости учитывает громкость окружения игрока.", "Speech can appear in chat, a bubble, or both. Execution mode → Before next step is the default: it waits for the duration before continuing; Alongside next step continues immediately. Duration 0 does not delay the script and keeps speech until replaced. For chat, set audience tags and distance, sending time and deletion after completion. Sound uses Foundry's file picker; its volume multiplier respects the player's ambient-volume setting."),
    section("emotion", "Показать эмоцию над объектом", "Show an emotion above an object", "Выберите действие «Эмоция». Введите один символ или нажмите ☺ рядом с полем. Верхние значки прокручивают к четырём группам по 35 символов; выбор, клик снаружи или Escape закрывает окошко. «Размер» задаёт шрифт в пикселях карты: положительное число, включая дроби, по умолчанию 32. «Режим выполнения → Вместе со следующим» по умолчанию продолжает скрипт сразу; «До следующего» ждёт указанную длительность. Длительность 0 не задерживает скрипт и сохраняет эмоцию до замены. При одновременной реплике эмоция располагается над её пузырём, а после исчезновения пузыря возвращается к токену.", "Choose the Emotion action. Type one symbol or press ☺ beside the field. The top icons scroll to four groups of 35 symbols; selection, an outside click or Escape dismisses the picker. Size sets the font size in map pixels: a positive number, including fractions, default 32. Execution mode → Alongside next step is the default and continues immediately; Before next step waits for the duration. Duration 0 does not delay the script and keeps the emotion until replaced. With simultaneous speech, the emotion sits above its bubble and returns to the token when the bubble disappears."),
    section("state", "Переключить несколько групп скриптом", "Change several groups from a script", "Выберите функцию «Состояние» и добавьте строки «Группа → Состояние». Каждую группу можно указать один раз. Пустой список ничего не меняет. Запущенные группы продолжают работать в выбранном состоянии, остановленные остаются остановленными. Указание уже текущего состояния ничего не перезапускает. Если переключается собственная группа объекта, старый скрипт больше не продолжается. Отказ проверки перехода до переключения оставляет выбранные состояния прежними.", "Choose the State function and add Group → State rows. Each group may appear once. An empty list changes nothing. Running groups continue in the selected state; stopped groups remain stopped. Selecting the current state does not restart it. If the object's own group changes state, its old script stops continuing. A transition validation denial before switching leaves the selected states unchanged."),
    section("approach", "Подвести объект к цели", "Bring an object to a target", "Выберите «Приблизиться» сразу после «Перемещения». Вставьте UUID объекта текущей сцены из его «Информации». Расстояние 0 означает касание границ; большее число оставляет промежуток в единицах сцены. Выберите длительность или скорость. Длительность 0 перемещает мгновенно. Это действие идёт по прямой сквозь препятствия к положению цели на момент начала шага.", "Choose Approach immediately after Move. Paste the current scene object's UUID from its Information window. Distance 0 means touching bounds; larger values leave a gap in scene units. Choose duration or speed. Duration 0 moves instantly. This action follows a straight line through obstacles to the target's position when the step starts."),
    section("follow", "Следовать за объектом", "Follow an object", "В «Следовать» укажите UUID цели, минимальное и максимальное расстояния и скорость. За максимальной дистанцией объект догоняет цель до минимальной; слишком близкое положение само по себе не заставляет отходить назад. По умолчанию он повторяет траекторию цели; режим «По прямой» двигает к цели без поиска обхода и останавливает у непреодолимого препятствия. «Завершать по» выбирает переход к следующему шагу при достижении цели (по умолчанию) либо следование до смены состояния. Пауза и ручная остановка прерывают движение.", "In Follow, enter the target UUID, minimum and maximum distances, and speed. Beyond the maximum distance, the object catches up to the minimum; being too close does not make it retreat. By default it follows the target's trajectory. Straight line moves toward the target without route finding and stops at an impassable obstacle. Finish on chooses the next step upon reaching the target (default), or continued following until a state change. Pausing and manual stopping interrupt movement."),
    section("script-dialogue", "Начать разговор с персонажами", "Start conversations with characters", "Выберите «Диалог», зарегистрированный в «Свойствах» объекта. В «Персонажи» вставьте UUID токенов текущей сцены, по одному в строке. Это команда мастера: разговор открывается активному владельцу персонажа независимо от условий «Действий игроков» и не расходует их кратность. «Ожидание» позволяет дождаться всех разговоров, первого завершённого или продолжить сразу. Последняя страница остаётся открытой до «Уйти» или закрытия окна; отключившийся участник освобождает ожидание после истечения срока сессии.", "Choose a Dialogue registered in the object's Properties. In Characters, paste token UUIDs from the current scene, one per line. This is a GM command: it opens for the active character owner regardless of Player actions conditions and does not consume their usage limit. Waiting allows all conversations, the first completed conversation, or immediate continuation. The last page stays open until Leave or window closure; a disconnected participant releases the wait when the session lease expires."),
    section("signals", "Вызвать реакцию других объектов", "Request a reaction from other objects", "Шаг «Сигнал» предлагает сигналы этого объекта; заполните их параметры. Шаг «Макрос» предлагает только прикреплённые объекту макросы. Для обоих шагов можно задать ожидание до и после выполнения. Ошибка макроса не должна оставаться незаметной: проверьте уведомление и исправьте его через редактор Foundry.", "Signal offers signals declared by this object; fill their parameters. Macro offers only macros attached to this object. Both actions can wait before and after execution. Check error notifications and fix the macro using Foundry's editor."),
    section("combat", "Использовать скрипт в бою", "Use a script in combat", "При поддержке боя включите «Использование в бою → Использовать». Задайте длительность хода и уведомления. «Подтверждать действие» позволяет продолжить, пропустить текущий ход или остановить скрипт в этом бою. Длительные действия продолжаются по ходам; после ручного вмешательства движение продолжится к подготовленной цели. «Завершать ход» изначально выключено.", "When combat is supported, enable Combat use → Use in combat. Set turn duration and notifications. Confirm action lets you continue, skip this turn, or stop the script for this combat. Long actions continue across turns; after manual intervention, movement continues toward the prepared destination. End turn is off by default."),
    section("dialogue-launch", "Выбрать способ запуска диалога", "Choose how to start a dialogue", "Действие «Диалог» используйте в переходах и рутине запущенной группы. Восстановление исходного состояния вручную не открывает игровые диалоги. Для ручного показа без автоматизации откройте окно «Диалоги». Если пауза или смена боевого хода застали открытие нескольких разговоров, Ширма продолжит его после допуска без повторного открытия уже созданных сессий.", "Use the Dialogue action in transitions and routines of a running group. Manually restoring the initial state does not open live dialogues. For a manual presentation without automation, use the Dialogues window. If a pause or combat turn change interrupts opening several conversations, Master screen resumes when allowed without reopening sessions it has already created."),
    section("pause", "Поговорить с занятым НИП", "Talk to a busy NPC", "Выберите своего персонажа или поставьте таргет на нём и кликните НИП. Также можно подвести персонажа к нему. Открытый игроком магазин или диалог прерывает скрипт согласно настройке «Взаимодействием с игроком». Выбранное продолжение начнётся после завершения всех взаимодействий. Для разговоров, начатых самим скриптом, действует его настройка «Ожидание». Пропущенное время не наверстывается. «Стоп» и ручное отключение автоматизации всегда имеют приоритет.", "Select or target your own character and click the NPC, or approach it. A player-opened shop or dialogue interrupts the script according to Player interaction. The chosen continuation starts after all interactions finish. Conversations started by the script itself follow its Waiting setting. Missed time is not caught up. Stop and manual automation disabling always take priority.")
  ] },
  { id: "catalog-tools", ru: "Подготовить магазины и диалоги", en: "Prepare shops and dialogues", sections: [
    section("shop", "Создать общий ассортимент", "Create shared stock", "В «Инструменты → Магазины» создайте магазин, задайте имя, арт, отображение и подтверждение мастера. Перетащите предметы Foundry в ассортимент и укажите запас целых предметов. Зарегистрируйте магазин в «Поведение → Свойства», затем разрешите его в «Действиях игроков» для нужных состояний. Все точки доступа разделяют один остаток и одну торговую сессию.", "In Tools → Shops, create a shop and set its name, art, display and GM approval. Drop Foundry items into its catalog and set stock of complete items. Register it in Behavior → Properties, then allow it under Player actions for the required states. All access points share stock and one trading session."),
    section("dialogue", "Собрать разговор", "Prepare a conversation", "В «Инструменты → Диалоги» создайте диалог с уникальным названием. Добавьте блоки текста, выберите начальный блок и изображения штатным менеджером Foundry. Ответ может продолжить разговор или закончить его и испустить настроенный сигнал диалога. Подписки на выбор ответа могут завершить или приостановить разговор; приостановленный разговор доступен как «Продолжить диалог».", "In Tools → Dialogues, create a dialogue with a unique name. Add text blocks, choose the starting block and select images with Foundry's file picker. A reply may continue or end the conversation and emit a configured dialogue signal. Reply subscriptions can finish or suspend it; a suspended conversation offers Resume dialogue."),
    section("preview", "Проверить условия без запуска", "Check conditions without running", "Нажмите «Предпросмотр», выберите группу, состояние, объект, персонажа, теги, дальность и видимость. При необходимости включите просмотр содержимого даже при отказе: причина останется видна. Эмуляция не меняет предметы, остатки, счётчики или состояния сцены и не отправляет сигналы.", "Choose Preview, then select the group, state, object, character, tags, range and visibility. You may show content even when admission fails; its reason stays visible. Emulation changes no items, stock, counters or scene states and emits no signals."),
    section("play", "Проверить от лица игрока", "Try it as a player", "Явно запустите группу в Режиссёре. Игрок выбирает своего персонажа и обращается к объекту. Допущенные магазины и диалоги появляются в меню; при нескольких инструментах видны их названия. Одновременно магазин обслуживает одного игрока и одного персонажа. Мастер видит активные сделки в окне «Магазины».", "Explicitly start the group in Director. The player selects their character and interacts with the object. Eligible shops and dialogues appear in its menu, with names when several are available. A shop serves one player and one character at a time. The GM can inspect active trades in Shops.")
  ] }
];

export const OBJECT_HELP_SETTINGS = [
  { id: "settings-commands", ru: "Настройки команд", en: "Command settings", fields: [
    ['[name="command-interruption-combat"]', "combat", "Боем", "Combat", "Прервать команду (по умолчанию), либо после боя повторить текущую фазу, перейти к следующей или начать команду заново. Фазы: скрипт до, встроенное действие, скрипт после.", "Stop the command (default), or after combat restart its current phase, go to the next phase or restart the command. Phases are the preceding script, built-in action and following script."],
    ['[name="command-interruption-interaction"]', "interaction", "Взаимодействием с игроком", "Player interaction", "Прервать команду (по умолчанию), либо после взаимодействия повторить текущую фазу, перейти к следующей или начать команду заново.", "Stop the command (default), or after the interaction restart its current phase, go to the next phase or restart the command."],
    ['[name="command-interruption-manual"]', "manual", "Ручной остановкой", "Manual stop", "Останавливает команду немедленно. Выбранное продолжение с текущей, следующей или первой фазы возможно только после явного запуска мастером. По умолчанию команда прерывается.", "Stops the command immediately. Continuing from the current, next or first phase requires an explicit GM start. By default the command is cancelled."],
    ['[name="command-interruption-error"]', "error", "Ошибкой", "Error", "Прервать команду (по умолчанию), либо после таймаута повторить текущую фазу, перейти к следующей или начать команду заново. Повторы ограничены счётчиком; выполненные действия не откатываются.", "Stop the command (default), or after the delay restart its current phase, go to the next phase or restart the command. Retries are limited; completed actions are not rolled back."],
    ['[name="command-interruption-retries"]', "retries", "Повторов после ошибки", "Retries after an error", "Лимит повторных попыток после первоначальной, от 1 до 10; по умолчанию 3. Общий для текущего запуска команды. При «Прервать» настройка сохраняется, но не действует.", "Retry budget after the initial attempt, from 1 to 10; default 3. Shared by this command run. Stop preserves the setting but disables its use."],
    ['[name="command-interruption-delay"]', "delay", "Таймаут повторений, с", "Retry delay, seconds", "Ожидание перед повторной попыткой команды после ошибки: от 0,1 до 60 секунд, по умолчанию 1. При «Прервать» настройка не действует.", "Wait before retrying the command after an error: 0.1 to 60 seconds, default 1. Unused when Stop is selected."],
    ['[data-command-enabled]', "enabled", "Включена", "Enabled", "Разрешает выдавать эту команду объекту при выполнении условий. По умолчанию выключено; настройки сохраняются при выключении.", "Allows this command when its conditions pass. Off by default; disabling preserves the configuration."],
    ['[name="command-allow"]', "allow", "Разрешающие теги", "Allowed tags", "Теги командующего персонажа через запятую. Достаточно любого совпадения; пустой список не ограничивает.", "Comma-separated tags of the commanding character. Any match is sufficient; an empty list does not restrict access."],
    ['[name="command-deny"]', "deny", "Запрещающие теги", "Denied tags", "Любой совпавший тег командующего персонажа запрещает команду, даже если есть разрешающий тег.", "Any matching commanding-character tag blocks the command, even when an allowed tag also matches."],
    ['[name="command-range"]', "range", "Расстояние, ед.", "Range, scene units", "Максимальное расстояние между командующим персонажем и исполнителем при выдаче команды. Ноль допустим, отрицательное значение — нет.", "Maximum distance between the commanding character and performer when issuing the command. Zero is allowed; negative values are not."],
    ['[name="command-group"]', "group", "Принимать в этой группе", "Accept in this group", "Команда доступна в выбранных группах и их состояниях. Если ни одна группа не отмечена, ограничения по группам нет.", "The command is available in the selected groups and their states. If no group is selected, groups do not restrict access."],
    ['[name="command-state"]', "state", "Состояние", "State", "Допустимое состояние отмеченной группы. Без отмеченных состояний допускаются все состояния этой группы.", "An allowed state of the selected group. Without selected states, all of that group's states are allowed."],
    ['[name="command-param-speed"]', "speed", "Скорость, ед./с", "Speed, units/sec.", "Положительная скорость движения в единицах сцены за секунду; по умолчанию 5. Препятствия проверяются во время движения.", "Positive movement speed in scene units per second, default 5. Obstacles are checked during movement."],
    ['[name="command-param-duration"]', "duration", "Длительность, с", "Duration, seconds", "Положительное ограничение времени движения; по умолчанию 10 секунд. Ноль не означает бесконечное движение.", "A positive movement time limit, default 10 seconds. Zero does not mean unlimited movement."],
    ['[name="command-param-seconds"]', "seconds", "Время ожидания, с", "Wait, seconds", "Команда «Жди» удерживает объект на месте указанное время, после чего завершается. Положительное число, по умолчанию 10 секунд.", "Wait holds the object in place for this time, then completes. A positive number, default 10 seconds."],
    ['[name="command-param-waitSeconds"]', "wait", "Ожидание после команды, с", "Wait after command, seconds", "После «Встань там» или «Отмена» объект ждёт это время. Положительное число, по умолчанию 1 секунда.", "After Stand there or Cancel, the object waits for this time. A positive number, default 1 second."],
    ['[name="command-param-minDistance"]', "minimum", "Минимальное расстояние", "Minimum distance", "На этой дистанции от границ командующего персонажа следование перестаёт приближать исполнителя. Ноль означает касание.", "At this gap from the commanding character's bounds, following stops bringing the performer closer. Zero means touching."],
    ['[name="command-param-maxDistance"]', "maximum", "Максимальное расстояние", "Maximum distance", "При превышении этой дистанции исполнитель догоняет командующего. Значение не меньше минимального расстояния.", "Beyond this gap the performer catches up with the commanding character. Must be at least the minimum distance."],
    ['[name="command-param-mode"]', "mode", "Режим следования", "Following mode", "По траектории повторяет путь персонажа; по прямой движется к нему до препятствия без поиска обхода.", "Along trajectory repeats the character's route; Straight line heads toward them until blocked, without route finding."],
    ['[name="command-param-bright"]', "bright", "Яркий свет, ед.", "Bright light, units", "Радиус яркого света сопровождающего источника в единицах сцены. Ноль отключает яркую часть.", "Bright radius of the following light source in scene units. Zero disables the bright area."],
    ['[name="command-param-dim"]', "dim", "Тусклый свет, ед.", "Dim light, units", "Радиус тусклого света сопровождающего источника в единицах сцены. Ноль отключает тусклую часть.", "Dim radius of the following light source in scene units. Zero disables the dim area."],
    ['[name="command-param-issuer"]', "issuer", "Кто может выдать команду", "Who may issue the command", "«Стой»: мастер или все игроки. «Отмена»: мастер, командующий игрок или все игроки. Мастер сохраняет право вмешательства; остальные условия допуска проверяются.", "Stop: GM or all players. Cancel: GM, the commanding player, or all players. The GM retains control; other admission conditions still apply."]
  ] },
  { id: "settings-preview", ru: "Предпросмотр взаимодействия", en: "Interaction preview", fields: [
    ['[class~="ms-interaction-preview"] [name="groupId"]', "group", "Группа", "Group", "Группа для проверки условий. Подготовка и работа сцены не меняются.", "The group used to check conditions. Scene preparation and execution stay unchanged."],
    ['[class~="ms-interaction-preview"] [name="stateId"]', "state", "Состояние", "State", "Состояние для проверки доступности инструмента.", "The state used to check tool availability."],
    ['[class~="ms-interaction-preview"] [name="target"]', "target", "Объект", "Object", "Точка доступа к магазину или диалогу. Проверяется назначение выбранного инструмента этому объекту.", "The access point for the shop or dialogue. Its attachment is checked."],
    ['[class~="ms-interaction-preview"] [name="actorTokenId"]', "actor", "Персонаж", "Character", "Персонаж для репетиции. Предметы используются как локальная копия, исходный инвентарь не меняется.", "The rehearsing character. Items are copied locally; the original inventory stays unchanged."],
    ['[class~="ms-interaction-preview"] [name="tags"]', "tags", "Имитируемые теги", "Emulated tags", "Теги персонажа для проверки белого и чёрного списков.", "Character tags used to check allow and deny lists."],
    ['[class~="ms-interaction-preview"] [name="distance"]', "distance", "Расстояние", "Distance", "Имитируемое расстояние в единицах сцены.", "The emulated distance in scene units."],
    ['[class~="ms-interaction-preview"] [name="used"]', "used", "Использований", "Uses", "Сколько запусков считать уже потраченными для проверки лимита.", "How many activations to consider consumed when checking the limit."],
    ['[class~="ms-interaction-preview"] [name="enabled"]', "enabled", "Допуск включён", "Admission enabled", "Имитирует ручной флаг разрешения взаимодействия.", "Emulates the manual interaction-admission flag."],
    ['[class~="ms-interaction-preview"] [name="visible"]', "visible", "Объект виден", "Object visible", "Имитирует видимость объекта для выбранного персонажа.", "Emulates visibility from the chosen character."],
    ['[class~="ms-interaction-preview"] [name="halted"]', "halted", "Группа остановлена", "Group stopped", "Проверяет ограничения взаимодействия при остановке группы.", "Checks interaction restrictions while the group is stopped."],
    ['[class~="ms-interaction-preview"] [name="showBlocked"]', "blocked", "Показать содержимое при отказе", "Show content when blocked", "Позволяет мастеру репетировать даже при отказе условий. Не открывает доступ игрокам.", "Lets the GM rehearse despite rejected conditions. It grants players no access."]
  ] },
  { id: "settings-scripts", ru: "Настройки скрипта", en: "Script settings", fields: [
    ['[name^="script-"][name$="-name"]', "name", "Название скрипта", "Script name", "Краткое имя в свёрнутом заголовке. Помогает отличать поведение состояний.", "A short name shown in the collapsed heading, helping distinguish state behaviors."],
    ['[name^="script-"][name$="-enabled"]:not([name*="-combat-"])', "enabled", "Включить", "Enable", "Разрешает выполнение скрипта. Выключение сохраняет все шаги; по умолчанию включено.", "Allows script execution. Disabling preserves all steps; enabled by default."],
    ['[name^="script-"][name$="-repeat"]', "repeat", "Повторять", "Repeat", "После завершающего шага возвращает к шагу 1. По умолчанию выключено.", "Returns to step 1 after a terminal action. Off by default."],
    ['[name$="-interruption-combat"]', "interruption-combat", "Боем", "Combat", "Для скрипта без разрешения работать в бою: прервать (по умолчанию) либо после завершения боя начать текущий шаг, следующий шаг по переходам или весь скрипт заново. На разрешённый в бою скрипт эта настройка не влияет.", "For a script not allowed in combat: stop (default), or after combat ends restart the current step, follow its next graph destination, or restart the script. This setting does not affect scripts allowed in combat."],
    ['[name$="-interruption-interaction"]', "interruption-interaction", "Взаимодействием с игроком", "Player interaction", "Прервать (по умолчанию) либо после завершения всех взаимодействий начать текущий шаг, следующий шаг по переходам или весь скрипт заново. Собственный вызов диалога скриптом использует настройку ожидания диалога.", "Stop (default), or after all interactions finish restart the current step, follow its next graph destination, or restart the script. A script's own dialogue call uses its dialogue waiting setting."],
    ['[name$="-interruption-manual"]', "interruption-manual", "Ручной остановкой", "Manual stop", "Остановка действует немедленно при любом выборе. Продолжение с текущего шага, следующего шага по переходам или начала скрипта возможно только после явного запуска мастером. По умолчанию — прервать.", "Stopping takes effect immediately in every mode. Continuing from the current step, its next graph destination, or the beginning requires an explicit GM start. Stop is the default."],
    ['[name$="-interruption-command"]', "interruption-command", "Командой", "Command", "Прервать — по умолчанию; продолжение после команды задаётся с текущего шага, следующего по переходам или начала скрипта. «Игнорировать» позволяет текущему блоку закончиться: принятая команда ждёт его, новая рутина не начинается. В скриптах до/после команды по умолчанию выбрано «Игнорировать». Ручную аварийную остановку игнорировать нельзя.", "Stop is the default; after the command, continuation can restart the current step, follow its next graph destination, or restart the script. Ignore lets the current block finish: the accepted command waits and no new routine starts. Before/after command scripts default to Ignore. An emergency manual stop cannot be ignored."],
    ['[name$="-interruption-error"]', "interruption-error", "Ошибкой", "Error", "Прервать при ошибке (по умолчанию) либо после таймаута начать текущий шаг, следующий шаг по переходам или весь скрипт заново. Повторы ограничены счётчиком; уже выполненные действия не отменяются.", "Stop on error (default), or after the delay restart the current step, follow its next graph destination, or restart the script. Retries are limited; completed actions are not undone."],
    ['[name$="-interruption-retries"]', "interruption-retries", "Повторов после ошибки", "Retries after an error", "Повторные попытки после первоначальной: целое число от 1 до 10, по умолчанию 3. Лимит общий на запуск: успешный шаг, «Повторять» и ручное продолжение его не пополняют. После исчерпания скрипт останавливается. При «Прервать» значение сохраняется, но не действует.", "Retries after the initial attempt: an integer from 1 to 10, default 3. The budget is shared across the run: successful steps, Repeat and manual continuation do not replenish it. The script stops once exhausted. Stop preserves the value but disables its use."],
    ['[name$="-interruption-delay"]', "interruption-delay", "Таймаут повторений, с", "Retry delay, seconds", "Пауза перед каждой повторной попыткой после ошибки: от 0,1 до 60 секунд, допускаются дроби, по умолчанию 1 секунда. При выборе «Прервать» поле не действует, но сохраняет значение.", "Pause before each retry after an error: 0.1–60 seconds, including fractions; default 1 second. Stop disables this field but preserves its value."],
    ['[data-script-kind]', "function", "Функция", "Function", "Выберите действие. Его параметры заменятся подходящим шаблоном.", "Choose an action. Its parameters are replaced with the appropriate template."],
    ['[data-script-json]', "parameters", "Параметры (JSON)", "Parameters (JSON)", "Те же параметры, что в таблице; содержит и скрытые режимом поля. Изменения синхронизируются. Исправьте ошибки формата до сохранения.", "The same parameters as the table, including fields hidden by the current mode. Changes are synchronized. Correct format errors before saving."],
    ["[data-script-param='[\"emoji\"]']", "emotion", "Эмоция", "Emotion", "Один символ над объектом. Кнопка ☺ открывает выбор по группам; можно ввести свой символ или очистить поле.", "One symbol above the object. The ☺ button opens grouped choices; you may type your own symbol or clear the field."],
    ["[data-script-param='[\"size\"]']", "emotion-size", "Размер", "Size", "Размер эмоции в пикселях карты. Положительное число, допускаются дроби; по умолчанию 32. При масштабировании карты символ масштабируется вместе с ней.", "Emotion font size in map pixels. A positive number; fractions are allowed, default 32. The symbol scales with map zoom."],
    ["[data-script-param='[\"executionMode\"]']", "execution-mode", "Режим выполнения", "Execution mode", "«Вместе со следующим» сразу продолжает скрипт, пока эффект отображается; «До следующего» ждёт длительность. По умолчанию эмоция выполняется вместе со следующим шагом, реплика — до него. Длительность 0 в обоих режимах не задерживает скрипт и сохраняет эффект до замены.", "Alongside next step continues the script while the effect remains visible; Before next step waits for its duration. Emotion defaults to Alongside next step; Speech defaults to Before next step. Duration 0 in either mode does not delay the script and keeps the effect until replaced."],
    ['[data-script-state-group]', "state-group", "Группа", "Group", "Группа, которой скрипт сменит состояние. Дубли групп не допускаются; остальные группы не изменяются.", "The group whose state the script changes. Duplicate groups are not allowed; other groups are unchanged."],
    ['[data-script-state-value]', "state-target", "Состояние", "State", "Целевое состояние выбранной группы. Смена сохраняет её статус запуска автоматизации и проверяет разрешение перехода.", "The selected group's target state. Switching preserves its automation status and validates the transition."],
    ["[data-script-param='[\"targetUuid\"]']", "target-uuid", "Объект (UUID)", "Object (UUID)", "UUID объекта текущей сцены, к которому нужно приблизиться или за которым следовать. Скопируйте его из «Информации» объекта.", "UUID of the current scene object to approach or follow. Copy it from the object's Information window."],
    ["[data-script-param='[\"distance\"]']", "approach-distance", "Расстояние", "Distance", "Промежуток между границами объектов в единицах сцены. Ноль — касание, значение по умолчанию. «Приблизиться» игнорирует препятствия.", "Gap between object bounds in scene units. Zero means touching and is the default. Approach ignores obstacles."],
    ["[data-script-param='[\"minDistance\"]']", "follow-minimum", "Минимальное расстояние", "Minimum distance", "При догонянии движение прекращается на этой дистанции от границ цели. Ноль — касание.", "While catching up, movement stops at this gap from the target's bounds. Zero means touching."],
    ["[data-script-param='[\"maxDistance\"]']", "follow-maximum", "Максимальное расстояние", "Maximum distance", "За этой дистанцией объект начинает догонять цель. Не меньше минимального расстояния.", "Beyond this gap the object starts catching up. Must be at least the minimum distance."],
    ["[data-script-param='[\"speed\"]']", "movement-speed", "Скорость", "Speed", "Положительное число в единицах сцены за секунду. Длительность перемещения рассчитывается по пути и скорости.", "A positive number in scene units per second. Movement time is calculated from the route and speed."],
    ["[data-script-param='[\"mode\"]']", "follow-mode", "Режим", "Mode", "По траектории — повторять путь цели (по умолчанию). По прямой — идти к цели до препятствия без поиска обхода.", "Along trajectory repeats the target's path (default). Straight line heads toward the target until blocked, without route finding."],
    ["[data-script-param='[\"finishOn\"]']", "follow-finish", "Завершать по", "Finish on", "Достижению цели — перейти к следующему шагу (по умолчанию). Смене состояния — продолжать следование до смены состояния или остановки.", "Reaching the target advances to the next step (default). State change keeps following until the state changes or execution stops."],
    ["[data-script-param='[\"dialogueId\"]']", "script-dialogue", "Диалог", "Dialogue", "Диалог, зарегистрированный в свойствах объекта. Скриптовый запуск мастером не проверяет и не расходует условия действий игроков.", "A dialogue registered in the object's properties. A GM-scripted start bypasses and does not consume player-action conditions."],
    ["[data-script-param='[\"tokenUuids\"]']", "dialogue-characters", "Персонажи", "Characters", "UUID токенов текущей сцены, по одному в строке. Для каждого нужен активный владелец персонажа.", "Token UUIDs from the current scene, one per line. Each character needs an active owner."],
    ["[data-script-param='[\"waitMode\"]']", "dialogue-wait", "Ожидание", "Waiting", "Дожидаться всех диалогов — по умолчанию. Дождаться завершения первого из диалогов — любого первого завершившегося. Не дожидаться завершения диалогов — сразу продолжить этот скрипт.", "Wait for all dialogues is the default. Wait for the first dialogue to finish accepts whichever finishes first. Do not wait for dialogues continues this script immediately."],
    ['[name^="script-"][name$="-next"]', "next", "Переход", "Next", "Номер следующего шага; несколько номеров через запятую выбираются случайно. Пустое поле завершает скрипт.", "The next step ID; several comma-separated IDs choose randomly. Blank ends the script."],
    ['[name$="-combat-enabled"]', "combat", "Использовать в бою", "Use in combat", "Разрешает скрипту действовать в ход объекта без прерывания боем. Без этой настройки при начале боя действует выбранное поведение прерывания «Боем».", "Allows the script to act on the object's turn without combat interruption. Otherwise, starting combat applies the selected Combat interruption behavior."],
    ['[name$="-combat-confirm"]', "confirm", "Подтверждать действие", "Confirm action", "Перед продолжением предлагает мастеру продолжить, пропустить ход или остановить скрипт в бою. По умолчанию включено.", "Offers the GM Continue, Skip turn, or Stop script in combat. On by default."],
    ['[name$="-combat-warning"]', "warning", "Предупреждение", "Warning", "Показывает мастеру уведомление при передаче хода объекту.", "Shows the GM a notification when the object's turn starts."],
    ['[name$="-combat-chat"]', "chat", "В чате мастеру", "In GM chat", "Отправляет уведомление через Информатора только мастерам.", "Sends an Informer notification only to GMs."],
    ['[name$="-combat-end-turn"]', "end", "Завершать ход", "End turn", "Разрешает завершать ход после расчёта действий. По умолчанию выключено.", "Allows ending the turn after calculating actions. Off by default."],
    ['[name$="-combat-seconds"]', "seconds", "Длительность хода", "Turn duration", "Сколько секунд длительности действий расходуется за один ход. Положительное число, допускаются дроби.", "How many seconds of action duration a turn consumes. A positive number; fractions are allowed."]
  ] },
  { id: "settings-objects", ru: "Объекты и действия игроков", en: "Objects and player actions", fields: [
    ["register-shop", "register-shop", "Магазины", "Shops", "Выберите магазин из каталога и нажмите «Добавить». Для доступа игрока затем настройте «Действия игроков».", "Choose a catalog shop and press Add. Then configure Player actions to grant player access."],
    ["register-dialogue", "register-dialogue", "Диалоги", "Dialogues", "Выберите диалог из каталога и нажмите «Добавить». Он станет доступен скриптам объекта; условия самостоятельного запуска игроком настраиваются отдельно.", "Choose a catalog dialogue and press Add. It becomes available to the object's scripts; player-initiated access is configured separately."],
    ["object-player-character", "player", "Персонаж игрока", "Player character", "Отключает автоматизацию токена. Разрешает взаимодействия с объектами любых групп с проверкой владения и условий.", "Disables token automation. Allows interaction across groups with ownership and condition checks."],
    ["object-group", "owner", "Группа", "Group", "Единственная группа, управляющая автоматизацией объекта. Перед переназначением остановите затронутые группы.", "The single group controlling this object's automation. Stop affected groups before reassigning."],
    ["object-tags", "tags", "Теги", "Tags", "Теги объекта через запятую. Условия инструментов проверяют теги действующего персонажа.", "Comma-separated object tags. Tool conditions check the acting character's tags."],
    ["object-notes", "notes", "Заметки мастера", "GM notes", "Личные заметки подготовки. Enter сохраняет окно; Shift+Enter добавляет строку.", "Private preparation notes. Enter saves the window; Shift+Enter adds a line."],
    ["entryStateId", "entry", "Состояние входа", "Entry state", "Обязательное состояние, выбранное по умолчанию для явного запуска. Просмотр карты ничего не запускает.", "Required default state for an explicit start. Viewing the map starts nothing."],
    ["newOwnedObject", "add", "Объект группы", "Group object", "Выберите существующий объект сцены для назначения группе.", "Choose an existing scene object to assign to the group."],
    ["feature-asset", "asset", "Инструмент", "Tool", "Магазин или диалог для выбранного назначения. Каталог может использоваться несколькими объектами.", "The shop or dialogue for this attachment. Several objects may share the catalog."],
    ["feature-range", "range", "Дальность", "Range", "Максимальное расстояние до объекта в единицах сцены. Дополнительно проверяется видимость.", "Maximum distance to the object in scene units. Visibility is also checked."]
  ] },
  { id: "settings-tool-catalog", ru: "Каталоги инструментов", en: "Tool catalogs", fields: [
    ["assetName", "name", "Название", "Name", "Уникальное название среди магазинов или диалогов сцены.", "A unique name among the scene's shops or dialogues."],
    ["assetDescription", "description", "Описание", "Description", "Заметка о назначении инструмента для мастера.", "A note describing the tool's purpose to the GM."],
    ["shopImg", "image", "Изображение магазина", "Shop image", "Арт, отображаемый рядом с ассортиментом.", "Art shown beside the stock list."],
    ["shopStock", "stock", "Начальный запас", "Initial stock", "Количество целых предметов при первом запуске магазина. Изменение подготовки не пополняет действующие остатки.", "Complete items stocked when the shop first runs. Editing preparation does not replenish live stock."],
    ["dialogueStartPage", "start", "Первый блок", "First page", "С этого блока начинается обычный разговор. Предпросмотр выбранного блока может начинаться с другого места.", "Normal conversations start with this page. Previewing a selected page can start elsewhere."],
    ["dialoguePageName", "block-name", "Название блока", "Page name", "Название для подготовки и выбора переходов; не заменяет произнесённый текст.", "A preparation label used to select transitions; it does not replace spoken text."],
    ["dialoguePageText", "text", "Текст блока", "Page text", "Реплика объекта или описание, которое увидит участник при появлении блока.", "The object line or description participants see when this page appears."],
    ["dialoguePageArt", "art", "Изображение блока", "Page image", "Выберите или загрузите картинку штатной кнопкой Foundry. Она отображается рядом с текстом блока.", "Choose or upload an image with Foundry's file picker. It appears alongside the page text."],
    ["responseNextPage", "next", "Продолжение", "Continue to", "Следующий блок. Пустой выбор завершает разговор.", "The next block. An empty choice ends the conversation."],
    ["responseSignal", "signal", "Сигнал ответа", "Response signal", "Объявленный этим диалогом сигнал для выбранного ответа.", "A signal declared by this dialogue for the chosen reply."],
    ["responseParameters", "parameters", "Параметры сигнала (JSON)", "Signal parameters (JSON)", "Значения в формате JSON должны соответствовать полям сигнала.", "JSON values must match the signal's declared fields."]
  ] }
];
